//! Installer settings, generated by the NixOS limine module.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use anyhow::{Context, Result};
use serde::Deserialize;

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
#[allow(
    clippy::struct_excessive_bools,
    reason = "mirrors the boot.loader.limine options, shared with the Python installer"
)]
pub struct InstallConfig {
    pub distro_name: String,
    pub global_config: String,
    pub wallpapers: Vec<PathBuf>,
    pub limine_path: PathBuf,
    pub efi_boot_mgr_path: Option<PathBuf>,
    pub efi_mount_point: PathBuf,
    pub file_systems: BTreeMap<String, FileSystem>,
    pub luks_devices: Vec<String>,
    pub can_touch_efi_variables: bool,
    pub efi_support: bool,
    pub efi_removable: bool,
    /// Name of the removable media boot file for the host, e.g. `BOOTX64.EFI`.
    pub efi_boot_file: Option<String>,
    pub secure_boot: SecureBoot,
    pub bios_support: bool,
    pub bios_device: String,
    pub partition_index: Option<u32>,
    pub force: bool,
    pub enroll_config: bool,
    pub resolution: Option<String>,
    /// `0` keeps every generation.
    pub max_generations: usize,
    pub extra_entries: String,
    /// Destination relative to the ESP, mapped to its source.
    pub additional_files: BTreeMap<String, PathBuf>,
    pub validate_checksums: bool,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct FileSystem {
    pub fs_type: String,
    pub device: Option<PathBuf>,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SecureBoot {
    pub enable: bool,
    pub auto_generate_keys: bool,
    pub auto_enroll_keys: AutoEnrollKeys,
    pub sign_additional_files: SignAdditionalFiles,
    pub sbctl: Option<PathBuf>,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct AutoEnrollKeys {
    pub enable: bool,
    pub extra_args: Vec<String>,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct SignAdditionalFiles {
    pub enable: bool,
    pub skip: Vec<String>,
}

impl InstallConfig {
    pub fn load(path: &Path) -> Result<Self> {
        let json = std::fs::read(path).with_context(|| format!("reading {}", path.display()))?;
        serde_json::from_slice(&json).with_context(|| format!("parsing {}", path.display()))
    }
}
